mapper.select:
SELECT p.post_id AS postId, p.user_id AS userId, u.nickname AS authorName, u.avatar AS authorAvatar, p.title, p.content, p.images, p.like_count AS likeCount, p.comment_count AS commentCount, p.view_count AS viewCount, p.status, p.create_time AS createTime, p.update_time AS updateTime FROM forum_post p LEFT JOIN `user` u ON p.user_id = u.user_id
p.status = 1
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ${orderBy}
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM forum_post_like
WHERE post_id = #{postId} AND user_id = #{userId}

mapper.update:
UPDATE forum_post
SET view_count = view_count + 1
WHERE post_id = #{postId}

UPDATE forum_post
SET comment_count = comment_count + 1
WHERE post_id = #{postId}
